## ✅ Quick Sort in C (with Explanation)

```c
#include <stdio.h>

// 🔹 Partition function – places pivot in correct position
int partition(int arr[], int low, int high) {
    int pivot = arr[high]; // ✅ Pivot is last element
    int i = low - 1;        // i marks the smaller element boundary

    for (int j = low; j <= high - 1; j++) {
        if (arr[j] < pivot) {
            i++; // Move boundary right
            // Swap arr[i] and arr[j]
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    // Place pivot at correct position (i + 1)
    int temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;

    return i + 1; // Return pivot's position
}

// 🔹 Main Quick Sort function (recursive)
void quickSort(int arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high); // Partition index

        quickSort(arr, low, pi - 1);  // Left side of pivot
        quickSort(arr, pi + 1, high); // Right side of pivot
    }
}

// 🔹 Utility function to print array
void printArray(int arr[], int n) {
    for (int i = 0; i < n; i++)
        printf("%d ", arr[i]);
    printf("\n");
}

// 🔹 Driver
int main() {
    int arr[] = {10, 7, 8, 9, 1, 5};
